-- =====================================================================
-- CITIZEN AWARENESS PORTAL - SUPABASE DATABASE SCHEMA AND SEEDING
-- =====================================================================
-- This SQL script creates the necessary tables, enables Row-Level Security (RLS),
-- defines access control policies, and seeds the database with initial fallback data.
-- Paste these queries in your Supabase SQL Editor.
-- =====================================================================

-- Clean up existing tables if they exist (optional, uncomment if resetting)
-- DROP TABLE IF EXISTS public.feedback;
-- DROP TABLE IF EXISTS public.awareness_content;
-- DROP TABLE IF EXISTS public.government_updates;
-- DROP TABLE IF EXISTS public.government_links;
-- DROP TABLE IF EXISTS public.helplines;
-- DROP TABLE IF EXISTS public.faqs;
-- DROP TABLE IF EXISTS public.documents;
-- DROP TABLE IF EXISTS public.schemes;

-- =====================================================================
-- 1. TABLE CREATION
-- =====================================================================

-- Schemes Table
CREATE TABLE IF NOT EXISTS public.schemes (
    id TEXT PRIMARY KEY,
    key TEXT NOT NULL,
    slug TEXT NOT NULL,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    audience TEXT NOT NULL,
    description TEXT NOT NULL,
    eligibility TEXT,
    documents TEXT,
    benefits TEXT,
    process TEXT,
    apply_link TEXT DEFAULT '#',
    state TEXT DEFAULT 'All India',
    language TEXT DEFAULT 'en',
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Documents Table
CREATE TABLE IF NOT EXISTS public.documents (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    purpose TEXT NOT NULL,
    documents_required TEXT[] DEFAULT '{}',
    process TEXT[] DEFAULT '{}',
    link TEXT DEFAULT '#',
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- FAQs Table
CREATE TABLE IF NOT EXISTS public.faqs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    question TEXT NOT NULL,
    answer TEXT NOT NULL,
    category TEXT,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Helplines Table
CREATE TABLE IF NOT EXISTS public.helplines (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    number TEXT NOT NULL,
    category TEXT,
    availability TEXT DEFAULT '24x7',
    link TEXT,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Government Links Table
CREATE TABLE IF NOT EXISTS public.government_links (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title TEXT NOT NULL,
    category TEXT,
    url TEXT NOT NULL,
    description TEXT,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Government Updates Table
CREATE TABLE IF NOT EXISTS public.government_updates (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title TEXT NOT NULL,
    category TEXT NOT NULL,
    summary TEXT,
    date DATE NOT NULL,
    link TEXT DEFAULT '#',
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Awareness Content (Scams and Alerts) Table
CREATE TABLE IF NOT EXISTS public.awareness_content (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type TEXT NOT NULL CHECK (type IN ('scam', 'awareness')),
    title TEXT NOT NULL,
    warning TEXT NOT NULL,
    action TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Feedback Table
CREATE TABLE IF NOT EXISTS public.feedback (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT DEFAULT 'Anonymous',
    email TEXT,
    category TEXT DEFAULT 'general',
    message TEXT NOT NULL,
    rating INTEGER,
    language TEXT DEFAULT 'en',
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);


-- =====================================================================
-- 2. ROW-LEVEL SECURITY (RLS) POLICIES & PERMISSIONS
-- =====================================================================

-- Enable RLS on all tables
ALTER TABLE public.schemes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.faqs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.helplines ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.government_links ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.government_updates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.awareness_content ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.feedback ENABLE ROW LEVEL SECURITY;

-- Select policies (Allow anyone to read general data)
DROP POLICY IF EXISTS "Allow public read access to schemes" ON public.schemes;
CREATE POLICY "Allow public read access to schemes" ON public.schemes FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow public read access to documents" ON public.documents;
CREATE POLICY "Allow public read access to documents" ON public.documents FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow public read access to faqs" ON public.faqs;
CREATE POLICY "Allow public read access to faqs" ON public.faqs FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow public read access to helplines" ON public.helplines;
CREATE POLICY "Allow public read access to helplines" ON public.helplines FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow public read access to government_links" ON public.government_links;
CREATE POLICY "Allow public read access to government_links" ON public.government_links FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow public read access to government_updates" ON public.government_updates;
CREATE POLICY "Allow public read access to government_updates" ON public.government_updates FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow public read access to awareness_content" ON public.awareness_content;
CREATE POLICY "Allow public read access to awareness_content" ON public.awareness_content FOR SELECT USING (true);

-- Feedback policies (Allow public to write, but only authenticated dashboard/admin users to read)
DROP POLICY IF EXISTS "Allow public anonymous submissions to feedback" ON public.feedback;
CREATE POLICY "Allow public anonymous submissions to feedback" ON public.feedback FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Allow authenticated users to read feedback" ON public.feedback;
CREATE POLICY "Allow authenticated users to read feedback" ON public.feedback FOR SELECT TO authenticated USING (true);

-- Grant access permissions to Supabase service roles (anon, authenticated)
GRANT USAGE ON SCHEMA public TO anon, authenticated;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO anon, authenticated;
GRANT INSERT ON public.feedback TO anon, authenticated;


-- =====================================================================
-- 3. SEED DATA INSERTION
-- =====================================================================

