('pan_card', 'PAN Card', 'Permanent Account Number for all tax-related financial transactions', ARRAY['Aadhaar Card (serves as identity, address, and date of birth proof)', 'Recent passport size photographs (for physical forms)', 'Valid mobile number linked with Aadhaar']::TEXT[], ARRAY['Visit NSDL (Protean) or UTIITSL website', 'Fill Form 49A online for Indian Citizens', 'Choose e-KYC option for instant digital PAN using Aadhaar OTP', 'Pay application fee of around Rs. 107 online', 'Physical PAN card will be delivered to your Aadhaar address, and e-PAN is sent to your email']::TEXT[], 'https://www.onlineservices.nsdl.com/'),
('aadhaar_card', 'Aadhaar Card', '12-digit unique identity number based on biometrics and demographics', ARRAY['Proof of Identity (Passport/Voter ID)', 'Proof of Address (Utility Bill/Bank statement)', 'Proof of Date of Birth (Birth Certificate/Marksheet)']::TEXT[], ARRAY['Locate and book an appointment at the nearest Aadhaar Enrolment Centre', 'Fill the Aadhaar enrolment form at the center', 'Provide biometric data (iris scan, fingerprints) and a photograph', 'Submit copies of identity and address proofs for scanning', 'Receive an acknowledgment slip with EID; track status online and download e-Aadhaar']::TEXT[], 'https://uidai.gov.in/'),
('e_shram_card', 'e-Shram Card', 'National database of unorganized workers to deliver social security benefits', ARRAY['Aadhaar Card', 'Aadhaar linked active mobile number', 'Bank Account details (account number and IFSC code)']::TEXT[], ARRAY['Visit the e-Shram self-registration portal', 'Enter your Aadhaar-linked mobile number and solve captcha', 'Enter Aadhaar details and authenticate using OTP', 'Fill personal, address, qualification, occupation, and bank details', 'Verify the details and download the e-Shram card containing a 12-digit UAN number']::TEXT[], 'https://eshram.gov.in/'),
('udyam_registration', 'Udyam (MSME) Registration', 'Official registration for small, micro, and medium enterprises to claim subsidies', ARRAY['Aadhaar Card of the proprietor/partner/director', 'PAN Card of the organization', 'GSTIN (if applicable)', 'Bank Account number and IFSC code']::TEXT[], ARRAY['Visit the Udyam Registration portal', 'Enter Aadhaar number and name of entrepreneur, validate with OTP', 'Enter PAN card details and validate tax status', 'Provide business name, location, bank details, and investment figures', 'Submit and receive the Udyam Registration Certificate containing QR code instantly']::TEXT[], 'https://udyamregistration.gov.in/'),
('income_certificate', 'Income Certificate', 'Proof of annual income of a family for fee concessions and scholarships', ARRAY['Aadhaar Card', 'Salary slip or Form 16 (for salaried)', 'Affidavit declaring non-salaried income', 'Ration card or electricity bill', 'Land records (for farmers)']::TEXT[], ARRAY['Access the state e-District portal', 'Complete registration and fill the Income Certificate application form', 'Upload income declaration affidavit and supporting address proofs', 'Application undergoes review by the local revenue inspector', 'Download the digital certificate after approval from the Tehsildar']::TEXT[], 'https://www.myscheme.gov.in/'),
('land_possession', 'Land Possession Certificate (LPC)', 'Establishes legal possession over a piece of land', ARRAY['Registered land deed papers', 'Recent land tax payment receipt', 'Aadhaar Card', 'Voter List copy', 'Affidavit declaring land details']::TEXT[], ARRAY['Apply online on the state Land Records (Bhumi) portal or visit Circle Office', 'Fill application form with Khata/Khesra/Plot numbers', 'Submit copies of registered deeds and current revenue tax receipt', 'An Amin (surveyor) is deputed to measure and verify boundary possession', 'Circle Officer approves and issues LPC showing ownership details']::TEXT[], 'https://www.myscheme.gov.in/'),
('ration_card_surrender', 'Ration Card Surrender Certificate', 'Required when moving to another state or changing category', ARRAY['Active Ration Card', 'Aadhaar Card', 'Proof of transfer/relocation', 'Application form for surrender']::TEXT[], ARRAY['Submit application to District Supply Officer (DSO) or apply online', 'Provide active ration card details and reason for surrender', 'FCS department marks the card as inactive and generates surrender slip', 'Use this surrender slip to apply for a fresh ration card in your new location']::TEXT[], 'https://nfsa.gov.in/'),
('non_creamy_layer', 'OBC Non-Creamy Layer Certificate', 'Required to claim reservation benefits in education and government jobs', ARRAY['Community/Caste Certificate', 'Aadhaar Card', 'Parent''s Income Certificates / Form 16 for last 3 years', 'Affidavit declaring assets and income']::TEXT[], ARRAY['Apply through the e-District website or Citizen Service Centre', 'Submit caste proof and parents'' verified income details of the past three fiscal years', 'Revenue inspectors verify that family income is below the creamy layer threshold (currently Rs. 8 Lakh/year)', 'Tehsildar issues the NCL certificate, usually valid for one financial year']::TEXT[], 'https://www.myscheme.gov.in/')
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    purpose = EXCLUDED.purpose,
    documents_required = EXCLUDED.documents_required,
    process = EXCLUDED.process,
    link = EXCLUDED.link;

-- Seeding public.faqs Table from faqs.csv
INSERT INTO public.faqs (id, question, answer, category)
VALUES
(11, 'How can I check the status of my Aadhaar card update?', 'You can check your Aadhaar status online by visiting the UIDAI MyAadhaar portal and entering your 14-digit Enrolment ID (EID) along with the date and time from the acknowledgment slip.', 'Aadhaar'),
(12, 'What is the difference between a PAN card and an e-PAN?', 'A physical PAN card is a plastic card sent by post, whereas an e-PAN is a digitally signed PAN card issued in electronic format. Both are equally valid for all financial and tax transactions.', 'PAN'),
(13, 'How do I link my mobile number to my bank account for DBT?', 'Visit your bank branch with your Aadhaar card and passbook, fill out the DBT enablement/Aadhaar seeding form, and submit it. Some banks also allow this via net banking or ATMs.', 'Banking'),
(14, 'What should I do if my debit card is lost or stolen?', 'Immediately call your bank''s customer care helpline to block the card, or block it instantly using your mobile banking application or internet banking portal to prevent unauthorized transactions.', 'Banking'),
(15, 'How do I report a cybercrime or online financial fraud?', 'You can file a complaint online at the National Cyber Crime Reporting Portal (cybercrime.gov.in) or call the national cybercrime helpline number 1930 immediately.', 'Cyber Safety'),
(16, 'Can a student apply for multiple scholarships on the National Scholarship Portal?', 'While you can search and submit applications for multiple scholarships on NSP, you are generally eligible to receive only one scholarship per academic year, depending on the scheme terms.', 'Education'),
(17, 'Is my digital document in DigiLocker legally valid?', 'Yes, documents issued in DigiLocker are legally recognized on par with original physical documents under Rule 9A of the Information Technology (Preservation and Retention of Information by Intermediaries Providing Digital Locker Facilities) Rules, 2016.', 'DigiLocker'),
(18, 'What is PM Kisan e-KYC and is it mandatory?', 'Yes, e-KYC is mandatory for all PM Kisan beneficiaries to receive their financial benefits. You can complete it using OTP on the PM-Kisan portal or through biometrics at a nearby CSC center.', 'Agriculture'),
(19, 'How do I apply for a duplicate Voter ID card if my original is lost?', 'You can apply for a replacement Voter ID online on the Voter Service Portal (voters.eci.gov.in) by filling Form 8 and selecting the replacement category. A nominal fee or process may apply.', 'Voter ID'),
(20, 'What is the maximum income limit for getting an OBC Non-Creamy Layer certificate?', 'Currently, the family income threshold for the OBC Non-Creamy Layer status is Rs. 8 Lakh per annum. This excludes salary and agricultural income in certain cases.', 'Certificates'),
(21, 'How can I register my business under MSME?', 'You can register your enterprise free of cost on the official Udyam Registration portal (udyamregistration.gov.in). You only need your Aadhaar card, PAN, and basic business details.', 'Business'),
(22, 'How do I know if my ration card is active?', 'You can check your ration card status on your state''s Food and Civil Supplies Department portal by entering your Ration Card number, or via the Mera Ration mobile application.', 'Ration'),
(23, 'What is the validity period of an Income Certificate?', 'The validity of an Income Certificate depends on state rules, but it is typically valid for one financial year from its date of issue.', 'Certificates'),
(24, 'What is the KIRAN helpline?', 'KIRAN (1800-599-0019) is a free, 24/7 national helpline launched by the government to provide mental health support, counseling, and crisis management.', 'Helpline'),
(25, 'Who should I contact if a government official demands a bribe?', 'You can report corruption or bribe demands to the State Anti-Corruption Bureau (ACB) or the Vigilance Department. You can also file a complaint with the Central Vigilance Commission (CVC) online.', 'Governance'),
(26, 'How do I apply for a Senior Citizen Card?', 'You can apply through your state''s e-District portal or local social welfare department. You will need proof of age (showing 60+ years), address proof, and photographs.', 'Certificates'),
(27, 'What is the PM SVANidhi scheme?', 'PM SVANidhi is a micro-credit scheme that provides working capital loans of up to Rs. 10,000 (with subsequent higher tranches) to street vendors to restart their businesses.', 'Business'),
(28, 'Can I track my speed post passport delivery online?', 'Yes, once your passport is dispatched, you will receive a tracking number via SMS. You can track its location on the India Post tracking website (indiapost.gov.in).', 'Passport'),
(29, 'How do I update my address on my Driving License?', 'You can apply for a ''Change of Address'' on the Sarathi Parivahan portal. You will need to upload your current DL and valid address proof, pay the fee, and submit.', 'Driving License'),
(30, 'What is an e-Shram card and who is eligible?', 'The e-Shram card is for unorganized workers (like laborers, construction workers, street vendors, domestic help) aged 16-59. It helps them receive social security schemes directly.', 'Social Security')
ON CONFLICT (id) DO UPDATE SET
    question = EXCLUDED.question,
    answer = EXCLUDED.answer,
    category = EXCLUDED.category;

