(12, 'PAN-Aadhaar Linking Deadline Extended', 'Notification', 'The Central Board of Direct Taxes (CBDT) has extended the deadline for linking PAN with Aadhaar card to prevent PAN deactivation.', '2026-06-02', 'https://www.incometax.gov.in/'),
(13, 'Launch of PM Vishwakarma Scheme Portal', 'New Scheme', 'Prime Minister launches the new portal for PM Vishwakarma, allowing traditional artisans to register and claim incentives.', '2026-06-03', 'https://pmvishwakarma.gov.in/'),
