(24, 'Harish Iyer', 'harish.iyer@gmail.com', 'General', 'A very clean and secure site. Highly recommend it to everyone looking for schemes.', 5, 'en'),
(25, 'Nisha Patel', 'nisha.p@gmail.com', 'Suggestion', 'Add an alert system to email subscribers when new schemes are launched.', 4, 'en'),
(26, 'Gopal Sharma', 'gopal.s@gmail.com', 'General', 'The helpline numbers are up to date. Tried the cyber fraud line and it worked.', 5, 'en'),
