(28, 'Sita Ram', 'sita.ram@gmail.com', 'General', 'We need more awareness portals like this. Simple language makes it accessible.', 5, 'hi'),
(29, 'Karan Johar', 'karan.j@gmail.com', 'Suggestion', 'Highlighting top trending schemes on the home page would improve discovery.', 4, 'en'),
